"use client";

import { FolderItemMedia } from "@/components/folder-item-media";
import { cn, type FolderItem } from "@/lib/utils";
import { useState, type CSSProperties, type ReactNode } from "react";

function FileIconOne({ stroke }: { stroke: string }) {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={stroke} strokeWidth="1.5">
      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
      <path d="M14 2v6h6" />
    </svg>
  );
}

function FileIconTwo({ stroke }: { stroke: string }) {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={stroke} strokeWidth="1.5">
      <rect x="3" y="3" width="18" height="18" rx="2" />
      <path d="M3 9h18M9 21V9" />
    </svg>
  );
}

function FileIconThree({ stroke }: { stroke: string }) {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={stroke} strokeWidth="1.5">
      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
      <path d="M14 2v6h6M16 13H8M16 17H8" />
    </svg>
  );
}

const files = [
  { id: 1, bg: "#E0E7FF", stroke: "#6366F1", icon: FileIconOne, zIndex: 11, delay: "20ms" },
  { id: 2, bg: "#FEF3C7", stroke: "#D97706", icon: FileIconTwo, zIndex: 12, delay: "0ms" },
  { id: 3, bg: "#DCFCE7", stroke: "#16A34A", icon: FileIconThree, zIndex: 13, delay: "40ms" },
];

export type FolderMode = "inside" | "hover" | "cards";

export type FolderProps = {
  mode: FolderMode;
  items?: FolderItem[];
  renderItem?: (item: FolderItem, index: number) => ReactNode;
  innerContent?: ReactNode;
  /** Simulate hover/open (touch). When set, ignores mouse enter/leave. */
  forceOpen?: boolean;
  compact?: boolean;
  className?: string;
  folderColor?: string;
  hideTab?: boolean;
};

export function Folder({
  mode,
  items = [],
  renderItem,
  innerContent,
  compact = false,
  className,
  folderColor = "",
  hideTab = false,
  forceOpen,
}: FolderProps) {
  const animated = mode === "cards";
  const showInnerPreview = mode === "inside";
  const showCardIconPreview = mode === "cards";
  const [internalOpen, setInternalOpen] = useState(false);
  const open = forceOpen ?? internalOpen;
  const usePointerHover = forceOpen === undefined;
  const baseBackColor = folderColor || "#F5A623";
  const baseFrontColor = folderColor || "#F0B429";
  const width = compact ? 48 : 96;
  const height = compact ? 40 : 80;

  const containerStyle: CSSProperties = {
    width,
    height,
    perspective: compact ? 400 : 800,
    cursor: "pointer",
  };

  const clamped = Math.max(0, Math.min(3, items.length));
  const visibleIndexes =
    clamped === 0 ? [] : clamped === 1 ? [1] : clamped === 2 ? [0, 2] : [0, 1, 2];
  const innerVisible = items.slice(0, 7);
  const innerOverflow = Math.max(0, items.length - 7);

  return (
    <div
      className={cn("relative shrink-0", className)}
      style={containerStyle}
      onMouseEnter={() => usePointerHover && animated && setInternalOpen(true)}
      onMouseLeave={() => usePointerHover && animated && setInternalOpen(false)}
    >
      <div style={{ position: "absolute", inset: 0, background: baseBackColor, borderRadius: "0 10px 10px 10px" }}>
        {!hideTab ? (
          <div
            style={{
              position: "absolute",
              top: -13,
              left: 0,
              width: 36,
              height: 14,
              background: baseBackColor,
              borderRadius: "6px 6px 0 0",
            }}
          />
        ) : null}
      </div>

      {visibleIndexes.map((fileIndex, previewIndex) => {
        const file = files[fileIndex];
        if (!file) return null;
        const item = items[previewIndex];
        const transforms = [
          open ? "translateX(-34px) translateY(-36px) rotate(-20deg)" : "none",
          open ? "translateY(-40px) rotate(0deg)" : "none",
          open ? "translateX(34px) translateY(-36px) rotate(20deg)" : "none",
        ];
        const Icon = file.icon;

        return (
          <div
            key={`${file.id}-${fileIndex}`}
            style={{
              position: "absolute",
              width: compact ? 22 : 42,
              height: compact ? 30 : 54,
              borderRadius: 5,
              left: "50%",
              marginLeft: compact ? -11 : -21,
              top: compact ? 6 : 10,
              background: file.bg,
              border: "1px solid rgba(0,0,0,0.06)",
              zIndex: file.zIndex,
              transformOrigin: "bottom center",
              transform: compact || !animated ? "none" : transforms[fileIndex],
              transition: animated ? `transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) ${file.delay}` : "none",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {showCardIconPreview && item ? (
              <FolderItemMedia item={item} renderItem={renderItem} index={previewIndex} width={20} height={20} imgClassName="size-5 rounded-sm object-cover" />
            ) : (
              <Icon stroke={file.stroke} />
            )}
          </div>
        );
      })}

      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          height: "82%",
          background: baseFrontColor,
          borderRadius: 10,
          transformOrigin: "bottom center",
          transform: animated && open ? "rotateX(-35deg)" : "rotateX(0deg)",
          transition: animated ? "transform 0.42s cubic-bezier(0.34, 1.56, 0.64, 1)" : "none",
          zIndex: 20,
        }}
      >
        {showInnerPreview && (innerContent || items.length > 0) ? (
          innerContent ? (
            <div className="absolute inset-x-2 top-4 bottom-2 overflow-hidden">{innerContent}</div>
          ) : (
            <div className="absolute inset-x-2 top-4 bottom-2 flex flex-wrap content-start gap-1 overflow-hidden">
              {innerVisible.map((item, index) => (
                <span key={index} className="flex size-4 items-center justify-center rounded-sm border border-black/10 bg-white/90">
                  <FolderItemMedia item={item} renderItem={renderItem} index={index} />
                </span>
              ))}
              {innerOverflow > 0 ? (
                <span className="flex size-4 items-center justify-center rounded-sm bg-black/75 text-[9px] font-semibold text-white">
                  +{innerOverflow}
                </span>
              ) : null}
            </div>
          )
        ) : null}
        <div style={{ position: "absolute", top: 9, left: 9, right: 9, height: 1.5, background: "rgba(255,255,255,0.35)", borderRadius: 2 }} />
      </div>
    </div>
  );
}

import type { FolderItem } from "@/lib/utils";
import type { ReactNode } from "react";

export function FolderItemMedia({
  item,
  renderItem,
  index,
  width = 12,
  height = 12,
  imgClassName = "rounded-[2px] object-cover",
}: {
  item: FolderItem;
  renderItem?: (item: FolderItem, index: number) => ReactNode;
  index: number;
  width?: number;
  height?: number;
  imgClassName?: string;
}) {
  if (renderItem) return <>{renderItem(item, index)}</>;
  if (item.content != null) return <>{item.content}</>;
  if (!item.src && !item.fallback) return null;

  return (
    <img
      src={item.src || item.fallback}
      data-fallback={item.fallback}
      alt={item.alt ?? ""}
      width={width}
      height={height}
      className={imgClassName}
      draggable={false}
      onError={(e) => {
        const fb = e.currentTarget.dataset.fallback;
        if (fb && e.currentTarget.src !== fb) e.currentTarget.src = fb;
      }}
    />
  );
}

import { FolderItemMedia } from "@/components/folder-item-media";
import { cn, type FolderItem } from "@/lib/utils";
import type { ReactNode } from "react";

export function FolderHoverPopover({
  items,
  renderItem,
  maxVisible = 8,
  caret = "top",
  className,
}: {
  items: FolderItem[];
  renderItem?: (item: FolderItem, index: number) => ReactNode;
  maxVisible?: number;
  caret?: "top" | "bottom";
  className?: string;
}) {
  if (items.length === 0) return null;
  const visible = items.slice(0, maxVisible);
  const overflow = Math.max(0, items.length - maxVisible);

  return (
    <div
      className={cn(
        "relative w-fit min-w-[150px] max-w-[220px] rounded-xl border border-neutral-200 bg-white p-3 shadow-lg",
        className,
      )}
    >
      <div
        className={cn(
          "absolute left-1/2 size-4 -translate-x-1/2 rotate-45 bg-white",
          caret === "top"
            ? "-top-2 border-t border-l border-neutral-200"
            : "-bottom-2 border-b border-r border-neutral-200",
        )}
      />
      <div className="flex flex-wrap justify-center gap-2">
        {visible.map((item, i) => (
          <span
            key={i}
            className="flex size-6 items-center justify-center rounded-sm border border-neutral-200 bg-white p-0.5"
          >
            <FolderItemMedia
              item={item}
              renderItem={renderItem}
              index={i}
              width={20}
              height={20}
              imgClassName="size-5 rounded-sm object-cover"
            />
          </span>
        ))}
        {overflow > 0 ? <p className="text-xs text-neutral-600">+{overflow}</p> : null}
      </div>
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import type { ReactNode } from "react";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function faviconUrlForWebsite(url: string) {
  try {
    const host = new URL(url).hostname;
    if (!host) return "";
    return `https://www.google.com/s2/favicons?${new URLSearchParams({ domain: host, sz: "64" })}`;
  } catch {
    return "";
  }
}

export function fallbackIcon(seed: string) {
  const letter = (seed.trim().charAt(0) || "?").toUpperCase();
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='64' height='64'><rect width='64' height='64' rx='12' fill='#e5e7eb'/><text x='32' y='41' text-anchor='middle' font-size='30' fill='#374151'>${letter}</text></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

export type FolderItem = {
  src?: string;
  fallback?: string;
  alt?: string;
  content?: ReactNode;
};

export function itemFromUrl(url: string, label: string): FolderItem {
  return { src: faviconUrlForWebsite(url), fallback: fallbackIcon(label), alt: label };
}

export const demoFolderItems: FolderItem[] = [
  itemFromUrl("https://github.com", "GitHub"),
  itemFromUrl("https://www.notion.so", "Notion"),
  itemFromUrl("https://www.figma.com", "Figma"),
  itemFromUrl("https://linear.app", "Linear"),
  itemFromUrl("https://slack.com", "Slack"),
  itemFromUrl("https://vercel.com", "Vercel"),
];
